def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        chain_dict[a] = b

    current = chain_dict['fof']
    result = []

    while current:
        result.append(current)
        next_item = chain_dict.get(current)
        if next_item is None:
            break
        current = next_item

    return ','.join(result)
